import unittest
from stats import mean, median, mode

class TestStats(unittest.TestCase):
    def test_mean(self):
        self.assertAlmostEqual(mean([1, 2, 3, 4]), 2.5)

    def test_median_odd(self):
        self.assertEqual(median([5, 1, 3]), 3)

    def test_median_even(self):
        self.assertAlmostEqual(median([4, 1, 3, 2]), 2.5)

    def test_mode_smallest_of_most_frequent(self):
        self.assertEqual(mode([3, 1, 3, 1, 2]), 1)

    def test_empty_raises(self):
        for fn in (mean, median, mode):
            with self.assertRaises(ValueError):
                fn([])

if __name__ == "__main__":
    unittest.main()
